mapper.select:
SELECT DISTINCT c.id, c.class_name, c.class_code, c.department_id, c.grade, c.description, d.dept_name as department_name, c.create_time, c.update_time, c.deleted FROM class_info c LEFT JOIN department d ON c.department_id = d.id WHERE 1=1
AND c.department_id = #{departmentId}
ORDER BY c.create_time DESC

mapper.update:
UPDATE class_info
class_name = #{className}, class_code = #{classCode}, department_id = #{departmentId}, grade = #{grade}, description = #{description},
WHERE id = #{id}
